      }),
      this.tsm.checkedStats$.subscribe(stats => {
        this.checkedStats.set(stats);
        this.onCheckedChange(stats);
      }),
      this.tsm.commandResponses$.subscribe(commandResponse => {
        this.messages.push(this.commandResponseToMessage(commandResponse));
      }),
      this.tsm.commandResponses$
        .pipe(switchMap(() => interval(7000)))
        .subscribe(() => { this.messages.shift(); })
    ];

    this.mds.appSubTitle$.next(this.cts.getCustomText('gm_headline') ?? '');
    this.headerService.title = `${this.mds.appTitle$.value} ${this.mds.appSubTitle$.value} - ${this.groupLabel}`;
  }

  private commandResponseToMessage(commandResponse: CommandResponse): UIMessage {
    const command = this.cts.getCustomText(`gm_control_${commandResponse.commandType}`) || commandResponse.commandType;
    const successWarning = this.cts.getCustomText(`gm_control_${commandResponse.commandType}_success_warning`) || '';
    if (!commandResponse.testIds.length) {
      return {
        level: 'warning',
        text: 'Keine Tests Betroffen von: `%s`',
        customtext: 'gm_message_no_session_affected_by_command',
        replacements: [command, commandResponse.testIds.length.toString(10)]
      };
    }
    return {
      level: successWarning ? 'warning' : 'info',
      text: '`%s` an `%s` tests gesendet! %s',
      customtext: 'gm_message_command_sent_n_sessions',
      replacements: [command, commandResponse.testIds.length.toString(10), successWarning]
    };
  }

  ngOnDestroy(): void {
    this.routeChanged$.next();
    this.routeChanged$.complete();
    this.tsm.disconnect();
    this.subscriptions.forEach(subscription => subscription.unsubscribe());
  }

  ngAfterViewChecked(): void {
    this.isScrollable = this.mainElem.nativeElement.clientHeight < this.mainElem.nativeElement.scrollHeight;
  }

  private onSessionsUpdate(stats: TestSessionSetStat): void {
    this.displayOptions.highlightSpecies = (stats.differentBookletSpecies > 1);

    if (!this.tsm.checkingOptions.enableAutoCheckAll) {
      this.displayOptions.manualChecking = true;
    }

    this.bookletStates = stats.bookletStateLabels;
  }

  private onCheckedChange(stats: TestSessionSetStat): void {
    // the test commands act on the checked sessions, so the toolbar disables them when there are none
    this.checkedSessionCount = stats.numberOfSessions;

    if (stats.differentBookletSpecies > 1) {
      this.currentlySelected = null;
    }
  }

  // eslint-disable-next-line class-methods-use-this
  trackSession = (index: number, session: TestSession): string => session.data.testId;

  setTableSorting(sort: Sort): void {
    if (!sort.active || sort.direction === '') {
      return;
    }
    this.tsm.sortBy$?.next(sort);
  }

  setDisplayOption(option: TestViewDisplayOptionKey, value: TestViewDisplayOptions[TestViewDisplayOptionKey]): void {
    if (Object.keys(this.displayOptions).includes(option)) {
      (this.displayOptions as {
        [option in TestViewDisplayOptionKey]: TestViewDisplayOptions[TestViewDisplayOptionKey]
      })[option] = value;
    }
  }

  toggleBookletStatesColumn(column: string): void {
    this.displayOptions.bookletStatesColumns =
      (this.displayOptions.bookletStatesColumns.includes(column)) ?
        this.displayOptions.bookletStatesColumns.filter(c => c !== column) :
        [...this.displayOptions.bookletStatesColumns, column].sort();
  }

  scrollDown(): void {
    this.mainElem.nativeElement.scrollTo(0, this.mainElem.nativeElement.scrollHeight);
  }

  updateScrollHint(): void {
    const elem = this.mainElem.nativeElement;
    const reachedBottom = (elem.scrollTop + elem.clientHeight === elem.scrollHeight);
    elem.classList[reachedBottom ? 'add' : 'remove']('hide-scroll-hint');
  }

  getSessionColor(session: TestSession): string {
    const stripes = (c1: string, c2: string) => `repeating-linear-gradient(45deg, ${c1}, ${c1} 10px, ${c2} 10px, ${c2} 20px)`;
    const hsl = (h: number, s: number, l: number) => `hsl(${h}, ${s}%, ${l}%)`;
    const colorful = this.displayOptions.highlightSpecies && session.booklet.species;
    const h = colorful ? (
      session.booklet.species.length *
      session.booklet.species.charCodeAt(0) *
      session.booklet.species.charCodeAt(session.booklet.species.length / 4) *
      session.booklet.species.charCodeAt(session.booklet.species.length / 4) *
      session.booklet.species.charCodeAt(session.booklet.species.length / 2) *
      session.booklet.species.charCodeAt(3 * (session.booklet.species.length / 4)) *
      session.booklet.species.charCodeAt(session.booklet.species.length - 1)
    ) % 360 : 0;

    switch (session.state) {
      case 'paused':
        return hsl(h, colorful ? 45 : 0, 90);
      case 'pending':
      case 'locked':
        return stripes(hsl(h, colorful ? 75 : 0, 95), hsl(0, 0, 92));
      case 'error':
        return stripes(hsl(h, colorful ? 75 : 0, 95), hsl(0, 30, 95));
      default:
        return hsl(h, colorful ? 75 : 0, colorful ? 95 : 100);
    }
  }

  markElement(marking: Selected): void {
    this.CurrentlyMarked = marking;
  }

  selectElement(selected: Selected): void {
    this.tsm.checkSessionsBySelection(selected);
    this.currentlySelected = selected;
  }

  finishEverythingCommand(): void {
    const scope = this.bs.accessSignal;
    if (scope.aborted) return;
    this.subscriptions.push(this.messageService.showConfirmDialog({
      title: 'Testdurchführung beenden',
      content: 'Achtung! Diese Aktion sperrt und beendet sämtliche Tests dieser Sitzung.',
      confirmText: 'Ja, ich möchte die Testdurchführung beenden'
    }).pipe(
      take(1),
      filter((confirmed: boolean) => confirmed),
      tap(() => { this.isClosing = true; }),
      switchMap(() => this.tsm.commandFinishEverything()),
      delay(2000),
      takeUntil(this.routeChanged$),
      takeUntil(fromEvent(scope, 'abort')),
      finalize(() => { this.isClosing = false; })
    ).subscribe({
      next: () => { void this.router.navigateByUrl('/group-monitor'); },
      error: () => { this.messages.push({ level: 'error', customtext: '', text: 'Die Testdurchführung konnte nicht beendet werden.' }); }
    }));
  }

  testCommandGoto(): void {
    if (!this.currentlySelected?.element?.blockId) {
      this.messages.push({
        level: 'warning',
        customtext: 'gm_test_command_no_selected_block',
        text: 'Kein Zielblock ausgewählt'
      });
      return;
    }

    const selection = this.currentlySelected;
    const targets = this.tsm.checked;
    const ids = targets.map(session => session.data.testId);
    const scope = this.bs.accessSignal;
    if (scope.aborted) return;
    const current = () => this.currentlySelected === selection && scope === this.bs.accessSignal && !scope.aborted &&
      JSON.stringify(this.tsm.checked.map(session => session.data.testId)) === JSON.stringify(ids);
    this.subscriptions.push((targets
      .some(testSession => isBooklet(testSession.booklet) &&
          selection.element &&
          testSession.timeLeft &&
          (testSession.timeLeft[selection.element.id] <= 0)
      ) ?
      this.observeDialog(this.dialog.open(
        TimeRestrictionDialogComponent, {
          width: 'auto',
          data: <TimeRestrictionDialogData>{
            title:
                this.cts.getCustomText('gm_control_goto_unlock_blocks_confirm_headline'),
            content:
                this.cts.getCustomText('gm_control_goto_unlock_blocks_confirm_text'),
            confirmbuttonlabel: 'OK',
            showcancel: true,
            remainingTime: this.tsm.getMaxTimeAcrossAllSessions(selection)
          }
        }
      )) :
      of(1) // 1 as in 'true'
    ).pipe(
      take(1),
      filter((confirmed?: number | boolean) => !!confirmed && current()),
      switchMap(confirmed => this.tsm.testCommandGoto(selection, Number(confirmed), targets)),
      takeUntil(this.routeChanged$),
      takeUntil(fromEvent(scope, 'abort'))
    ).subscribe({
      next: () => { if (current()) this.selectNextBlock(); },
      error: () => { this.messages.push({ level: 'error', customtext: '', text: 'Der Sprung konnte nicht ausgeführt werden.' }); }
    }));
  }

  private selectNextBlock(): void {
    if (!this.displayOptions.autoselectNextBlock) return;
    if (!this.currentlySelected) return;
    if (!isBooklet(this.currentlySelected.originSession.booklet)) return;
    this.currentlySelected = {
      element: this.currentlySelected.element?.nextBlockId ?
        BookletUtil.getBlockById(
          this.currentlySelected.element.nextBlockId,
          this.currentlySelected.originSession.booklet
        ) : null,
      inversion: false,
      originSession: this.currentlySelected.originSession,
      nthClick: this.currentlySelected.nthClick
    };
  }

  unlockCommand(): void {
    this.tsm.testCommandUnlock();
  }

  toggleChecked(session: TestSession): void {
    if (!this.tsm.isChecked(session)) {
      this.tsm.checkSession(session);
    } else {
      if (session.data.testId === this.currentlySelected?.originSession?.data?.testId) {
        this.currentlySelected = null;
      }
      this.tsm.uncheckSession(session);
    }
  }

  invertChecked(event: Event): boolean {
    event.preventDefault();
    this.tsm.invertChecked();
    return false;
  }

  toggleAlwaysCheckAll(event: MatSlideToggleChange): void {
    if (this.tsm.checkingOptions.enableAutoCheckAll && event.checked) {
      // TODO not ideal - try to reset the state properly, instead of reloading the component
      this.componentUtilService.reloadComponent(true);
    } else {
      this.tsm.checkNone();
      this.displayOptions.manualChecking = true;
      this.tsm.checkingOptions.autoCheckAll = false;
      this.currentlySelected = null;
    }
  }

  toggleCheckAll(event: MatCheckboxChange): void {
    if (event.checked) {
      this.tsm.checkAll();
    } else {
      this.tsm.checkNone();
      this.currentlySelected = null;
    }
  }

  addFilter(): void {
    this.openFilterDialog();
  }

  editFilter(key: string): void {
    this.openFilterDialog(this.tsm.filterOptions[key]);
  }

  private observeDialog<T, R>(dialog: MatDialogRef<T, R>): Observable<R | undefined> {
    return this.initializeDialog(dialog).afterClosed().pipe(finalize(() => dialog.close()));
  }

  private initializeDialog<T, R>(dialog: MatDialogRef<T, R>): MatDialogRef<T, R> {
    // A zoneless overlay exposes its DOM before its scheduled first update.
    // Bind controls now so an immediate input cannot be overwritten by setup.
    dialog.componentRef?.changeDetectorRef.detectChanges();
    return dialog;
  }

  private openFilterDialog(filterEntry: TestSessionFilterListEntry | undefined = undefined) {
    const scope = this.bs.accessSignal;
    if (scope.aborted) return;
    const data = filterEntry ? filterEntry.filter : {};
    const dialogRef = this.initializeDialog(this.addFilterDialog.open(AddFilterDialogComponent, { width: 'auto', data, viewContainerRef: this.filterDialogView }));

    this.subscriptions.push(dialogRef.afterClosed().pipe(
      take(1), takeUntil(this.routeChanged$), takeUntil(fromEvent(scope, 'abort')),
      finalize(() => dialogRef.close())
    ).subscribe((newFilter: TestSessionFilter) => {
      if (!newFilter) return;
      this.tsm.filterOptions[newFilter.id] = {
        selected: true,
        filter: newFilter,
        source: filterEntry?.source || 'custom'
      };
      this.tsm.refreshFilters();
    }));
  }

  // eslint-disable-next-line class-methods-use-this
  sortFilterMenuEntries(
    a: KeyValue<string, TestSessionFilterListEntry>,
    b: KeyValue<string, TestSessionFilterListEntry>
  ): number {
    const aLevel = testSessionFilterListEntrySources.indexOf(a.value.source);
    const bLevel = testSessionFilterListEntrySources.indexOf(b.value.source);
    if (aLevel !== bLevel) return aLevel - bLevel;
    return a.value.filter.label > b.value.filter.label ? 1 : -1;
  }

  quickFilterOnUpdateModel() {
    if (!this.quickFilter) {
      this.tsm.filterOptions.quick.selected = false;
    } else {
      this.tsm.filterOptions.quick.selected = true;
      this.tsm.filterOptions.quick.filter.value = this.quickFilter;
    }

    this.tsm.refreshFilters();
  }

  toggleQuickFilterBox(): void {
    this.quickFilterBoxOpen = !this.quickFilterBoxOpen;
  }

  quickFilterOnFocusOut(): void {
    if (!this.quickFilter) this.quickFilterBoxOpen = false;
  }

  private applyProfile(p: Profile): void {
    if (isColumnOption(p.settings.blockColumn)) this.displayOptions.blockColumn = p.settings.blockColumn;
    if (isColumnOption(p.settings.unitColumn)) this.displayOptions.unitColumn = p.settings.unitColumn;
    if (isColumnOption(p.settings.groupColumn)) this.displayOptions.groupColumn = p.settings.groupColumn;
    if (isColumnOption(p.settings.bookletColumn)) this.displayOptions.bookletColumn = p.settings.bookletColumn;
    if (isViewOption(p.settings.view)) this.displayOptions.view = p.settings.view;
    if (isYesNoOption(p.settings.autoselectNextBlock)) this.displayOptions.autoselectNextBlock = p.settings.autoselectNextBlock !== 'no';

    (p.filters || [])
      .forEach((filter: TestSessionFilter, index: number) => {
        filter.id = `profile_filter:${index}`;
        this.tsm.filterOptions[filter.id] = { selected: true, filter, source: 'profile' };
      });

    this.displayOptions.bookletStatesColumns = (p.settings.bookletStatesColumns || '').split(/[\W,]+/);

    Object.entries(p.filtersEnabled || [])
      .forEach(([f, onOff]) => {
        if (this.tsm.filterOptions[f]) {
          this.tsm.filterOptions[f].selected = ['1', 'true', 'on', 'yes'].includes(onOff);
        }
      });
    this.tsm.refreshFilters();
  }
}

import { inject, Injectable } from '@angular/core';
import {
  BehaviorSubject, combineLatest, defer, EMPTY, fromEvent, interval, Observable, of, Subject, Subscription, zip
} from 'rxjs';
import type { Sort } from '@angular/material/sort';
import {
  delay, filter, mergeMap, map, startWith, switchMap, take, takeUntil, tap
} from 'rxjs/operators';
import { BackendService } from '../backend.service';
import { BookletService } from '../booklet/booklet.service';
import { TestSessionUtil } from '../test-session/test-session.util';
import {
  type CheckingOptions,
  type CommandResponse,
  type GotoCommandData,
  type GroupMonitorConfig,
  isBooklet,
  type Selected,
  type Testlet,
  type TestSession,
  type TestSessionFilter,
  type TestSessionFilterList,
  type TestSessionSetStat,
  TestSessionsSuperStates
} from '../group-monitor.interfaces';
import { BookletUtil } from '../booklet/booklet.util';
import { GROUP_MONITOR_CONFIG } from '../group-monitor.config';
import type { TestSessionByDataTestId } from './test-session-manager.interfaces';

@Injectable()
export class TestSessionManager {
  private readonly groupMonitorConfig=inject(GROUP_MONITOR_CONFIG);
  static readonly basicFilters: TestSessionFilterList = {
    locked: {
      selected: false,
      source: 'base',
      filter: {
        id: 'locked',
        label: 'gm_filter_locked',
        target: 'testState',
        value: 'status',
        subValue: 'locked',
        type: 'equal',
        not: false
      }
    },
    pending: {
      selected: false,
      source: 'base',
      filter: {
        id: 'pending',
        label: 'gm_filter_pending',
        target: 'testState',
        value: 'status',
        subValue: 'pending',
        type: 'equal',
        not: false
      }
    },
    quick: {
      selected: false,
      source: 'quick',
      filter: {
        id: 'quickFilter',
        label: 'gm_filter_quick',
        target: 'personLabel',
        value: '',
        subValue: '',
        type: 'substring',
        not: true
      }
    }
  };

  sortBy$: Subject<Sort>;
  filters$: Subject<TestSessionFilter[]>;
  filterOptions: TestSessionFilterList = {};
  checkingOptions: CheckingOptions = {
    enableAutoCheckAll: false,
    autoCheckAll: false
  };

  private groupName: string = '';
  private connectionRevision = 0;
  private readonly disconnected$ = new Subject<void>();
  private monitor$: Observable<TestSession[]> = new Observable<TestSession[]>();
  private _sessions$: BehaviorSubject<TestSession[]> = new BehaviorSubject<TestSession[]>([]);
  private _checked: { [sessionTestSessionId: string]: TestSession } = {};
  private _checkedStats$: BehaviorSubject<TestSessionSetStat>;
  private _sessionsStats$: BehaviorSubject<TestSessionSetStat>;
  private _commandResponses$: Subject<CommandResponse> = new Subject<CommandResponse>();
  private _clock$: Observable<number>;
  private monitorSubscription: Subscription | null = null;

  constructor(
    private bs: BackendService,
    private bookletService: BookletService,
  ) {
    this._checkedStats$ = new BehaviorSubject<TestSessionSetStat>(TestSessionManager.getEmptyStats());
    this._sessionsStats$ = new BehaviorSubject<TestSessionSetStat>(TestSessionManager.getEmptyStats());
    this.sortBy$ = new BehaviorSubject<Sort>({ direction: 'asc', active: 'personLabel' });
    this.filters$ = new BehaviorSubject<TestSessionFilter[]>([]);
    this._clock$ = this.groupMonitorConfig.checkForIdleInterval ?
      interval(this.groupMonitorConfig.checkForIdleInterval).pipe(startWith(0)) :
      of(0);
    this.resetFilters();
  }

  get sessions$(): Observable<TestSession[]> {
    return this._sessions$.asObservable();
  }

  get sessions(): TestSession[] {
    return this._sessions$.getValue();
  }

  get checked(): TestSession[] { // this is intentionally not an observable
    return Object.values(this._checked);
  }

  get sessionsStats$(): Observable<TestSessionSetStat> {
    return this._sessionsStats$.asObservable();
  }

  get checkedStats$(): Observable<TestSessionSetStat> {
    return this._checkedStats$.asObservable();
  }

  get commandResponses$(): Observable<CommandResponse> {
    return this._commandResponses$
      .pipe(
        filter(c => !!c)
      );
  }

  connect(groupName: string): void {
    this.disconnect();
    this.groupName = groupName;
    this.sortBy$.next({ direction: 'asc', active: 'personLabel' });
    this.filters$.next([]);
    this.checkingOptions = {
      enableAutoCheckAll: true,
      autoCheckAll: true
    };

    this._checkedStats$.next(TestSessionManager.getEmptyStats());
    this._sessionsStats$.next(TestSessionManager.getEmptyStats());
    // this._commandResponses$.next();

    this.monitor$ = this.bs.observeSessionsMonitor(groupName)
      .pipe(
        switchMap(sessionChanges => sessionChanges.length ? zip(
          ...sessionChanges
            .map(sessionChange => combineLatest([
              this.bookletService.getBooklet(sessionChange.bookletName),
              this._clock$
            ])
              .pipe(
                map(([booklet]) => TestSessionUtil.analyzeTestSession(sessionChange, booklet))
              )
            )
        ) : of([]))
      );

    this._sessions$.next([]);

    this.monitorSubscription = combineLatest([this.sortBy$, this.filters$, this.monitor$])
      .pipe(
        // eslint-disable-next-line max-len
        map(([sortBy, filters, sessions]) => this.sortSessions(sortBy, TestSessionManager.filterSessions(sessions, filters))),
        tap(sessions => this.synchronizeChecked(sessions))
      )
      .subscribe(this._sessions$);
  }

  disconnect(): void {
    this.connectionRevision++;
    this.disconnected$.next();
    this.groupName = '';
    this.monitorSubscription?.unsubscribe();
    this.bs.cutConnection();
    this._sessions$.next([]);
    this._checked={};
    this._sessionsStats$.next(TestSessionManager.getEmptyStats());
    this._checkedStats$.next(TestSessionManager.getEmptyStats());
  }

  switchFilter(filterId: string): void {
    this.filterOptions[filterId].selected = !this.filterOptions[filterId].selected;
    this.refreshFilters();
  }

  refreshFilters(): void {
    this.filters$.next(Object.values(this.filterOptions)
      .filter(filterOption => filterOption.selected)
      .map(filterOption => filterOption.filter)
    );
  }

  resetFilters(): void {
    this.filterOptions = {};
    Object.keys(TestSessionManager.basicFilters)
      .forEach(key => {
        this.filterOptions[key] = {
          selected: TestSessionManager.basicFilters[key].selected,
          source: TestSessionManager.basicFilters[key].source,
          filter: { ...TestSessionManager.basicFilters[key].filter }
        };
      });
  }

  private static filterSessions(sessions: TestSession[], filters: TestSessionFilter[]): TestSession[] {
    return sessions
      .filter(session => session.data.testId && BigInt(session.data.testId) > -1n) // testsession without testId is deprecated
      .filter(session => !TestSessionManager.applyFilters(session, filters));
  }

  private static applyFilters(session: TestSession, filters: TestSessionFilter[]): boolean {
    const regexTest = (regex: string, value: string): boolean => {
      try {
        return new RegExp(regex).test(value);
      } catch (e) {
        return false;
      }
    };
    // eslint-disable-next-line @typescript-eslint/no-shadow
    const apply = (subject: string, filter: TestSessionFilter, inverted: boolean = false): boolean => {
      if (filter.not && !inverted) return !apply(subject, filter, true);
      if (Array.isArray(filter.value)) return filter.value.includes(subject);
      const object = filter.subValue ? filter.subValue : filter.value;
      switch (filter.type) {
        case 'substring':
          return subject.includes(object);
        case 'equal':
          return subject === object;
        case 'regex':
          return regexTest(object, subject);
        default:
          return false;
      }
    };
    const filterOut: TestSessionFilter | undefined = filters
      .find((nextFilter: TestSessionFilter): boolean => {
        switch (nextFilter.target) {
          case 'groupName':
          case 'personLabel':
          case 'mode':
            return apply(session.data[nextFilter.target] || '', nextFilter);
          case 'bookletId':
            return apply(session.data.bookletName || '', nextFilter); // bookletId is clearer for XML-authors
          case 'unitId':
            return apply(session.data.unitName || '', nextFilter); // unitId is clearer for XML-authors
          case 'unitLabel':
            return apply(session.current?.unit?.label || '', nextFilter);
          case 'bookletLabel':
            return apply('metadata' in session.booklet ? session.booklet.metadata.label : '', nextFilter);
          case 'blockId':
            return apply(session.current?.ancestor?.blockId || '', nextFilter);
          case 'blockLabel':
            return apply(session.current?.ancestor?.label || '', nextFilter);
          case 'testState': {
            if (Array.isArray(nextFilter.value)) return false;
            if (typeof session.data.testState[nextFilter.value] === 'undefined') return nextFilter.not;
            return apply(session.data.testState[nextFilter.value], nextFilter);
          }
          case 'bookletStates': {
            if (Array.isArray(nextFilter.value)) return false;
            if (!session.bookletStates || typeof session.bookletStates[nextFilter.value] === 'undefined') return nextFilter.not;
            return apply(session.bookletStates[nextFilter.value], nextFilter);
          }
          case 'state': {
            return apply(session.state, nextFilter);
          }
          case 'bookletSpecies': {
            return apply(session.booklet.species || '', nextFilter);
          }
          default:
            return false;
        }
      });
    return typeof filterOut !== 'undefined';
  }

  private send(request: Observable<CommandResponse>): void {
    const scope = this.bs.accessSignal;
    if (!this.groupName || scope.aborted) return;
    request.pipe(
      takeUntil(this.disconnected$),
      takeUntil(fromEvent(scope, 'abort'))
    ).subscribe({
      next: response => this._commandResponses$.next(response),
      // BackendService already exposes the redacted failure to the view.
      error: () => {}
    });
  }

  testCommandPause(): void {
    const testIds = this.checked
      .filter(session => !TestSessionUtil.isPaused(session))
      .filter(session => !['pending', 'locked'].includes(session.state))
      .map(session => session.data.testId);
    if (!testIds.length) {
      this._commandResponses$.next({ commandType: 'pause', testIds });
      return;
    }
    this.send(this.bs.command('pause', [], testIds));
  }

  testCommandResume(): void {
    const testIds = this.checked
      .filter(session => !['pending', 'locked'].includes(session.state))
      .map(session => session.data.testId);
    if (!testIds.length) {
      this._commandResponses$.next({ commandType: 'resume', testIds });
      return;
    }
    this.send(this.bs.command('resume', [], testIds));
  }

  testCommandGoto(selection: Selected, newTimeLeft: number, targets: TestSession[] = this.checked): Observable<true> {
    const gfg = TestSessionManager.groupForGoto(targets, selection);
    const allTestIds = targets.map(s => s.data.testId);
    const group = this.groupName;
    const revision = this.connectionRevision;
    const scope = this.bs.accessSignal;
    return defer(() => group && group === this.groupName && revision === this.connectionRevision &&
      scope === this.bs.accessSignal && !scope.aborted ? zip(
        Object.keys(gfg).map(unitAlias => this.bs.command(
          'goto',
          ['id', unitAlias, gfg[unitAlias].isClosed ? `| closed timeblock reopened - new remaining time ${newTimeLeft}` : ''],
          gfg[unitAlias].ids))
      ).pipe(
        takeUntil(this.disconnected$),
        takeUntil(fromEvent(scope, 'abort')),
        tap(() => { this._commandResponses$.next({ commandType: 'goto', testIds: allTestIds }); }),
        map(() => true as const)
      ) : EMPTY);
  }

  testCommandUnlock(): void {
    const testIds = this.checked
      .filter(session => TestSessionUtil.isLocked(session))
      .map(session => session.data.testId);

    if (!testIds.length) {
      this._commandResponses$.next({ commandType: 'unlock', testIds });
      return;
    }

    this.send(this.bs.unlock(this.groupName, testIds));
  }

  commandFinishEverything(): Observable<CommandResponse> {
    // Finish targets come from a fresh complete snapshot. Keep the visible
    // filter and auto-selection intact if the operation fails or is cancelled.
    const group = this.groupName;
    const revision = this.connectionRevision;
    const scope = this.bs.accessSignal;
    const current = () => !!group && revision === this.connectionRevision &&
      group === this.groupName && scope === this.bs.accessSignal && !scope.aborted;
    // Rendered rows may still await XML, or retain an older poll. Finish uses
    // one fresh complete native snapshot, then keeps those exact targets even
    // when the successful lock changes later snapshots to status=locked.
    return defer(() => current() ? this.bs.getSessionsMonitor(group).pipe(
      take(1),
      switchMap(rows => {
        if (!current()) return EMPTY;
        const unlocked = rows.filter(row => BigInt(row.testId) > 0n &&
          !TestSessionUtil.hasState(row.testState, 'status', 'locked'));
        const lockIds = unlocked.map(row => row.testId);
        const pending = new Set(this.bs.pendingFinishTargets(group));
        const eligible = rows.filter(row => BigInt(row.testId) > 0n &&
          !TestSessionUtil.hasState(row.testState, 'status', 'pending') &&
          !TestSessionUtil.hasState(row.testState, 'CONTROLLER', 'TERMINATED'));
        const remaining = new Set(eligible.map(row => row.testId));
        for (const id of pending) if (!remaining.has(id)) pending.delete(id);
        const terminateIds = eligible.filter(row => pending.has(row.testId) ||
          (!TestSessionUtil.hasState(row.testState, 'status', 'locked') &&
            (TestSessionUtil.hasState(row.testState, 'CONNECTION', 'POLLING') ||
              TestSessionUtil.hasState(row.testState, 'CONNECTION', 'WEBSOCKET'))))
          .map(row => row.testId);
        // Retain before writing: even an error/abort can follow a committed
        // lock. A retry uses a fresh snapshot without adopting unrelated locks.
        terminateIds.forEach(id => pending.add(id));
        this.bs.rememberFinishTargets(group, [...pending]);
        return this.bs.lock(group, lockIds).pipe(
          delay(1500),
          mergeMap(() => current() ? this.bs.command('terminate', ['lock'], terminateIds) : EMPTY),
          tap(() => {
            if (current()) this.bs.rememberFinishTargets(group,
              this.bs.pendingFinishTargets(group).filter(id => !terminateIds.includes(id)));
          })
        );
      }),
      takeUntil(this.disconnected$),
      takeUntil(fromEvent(scope, 'abort'))
    ) : EMPTY);
  }

  sortSessions(sort: Sort, sessions: TestSession[]): TestSession[] {
    return sessions
      .sort((session1, session2) => {
        const sortDirectionFactor = (sort.direction === 'asc' ? 1 : -1);
        if (sort.active === 'timestamp') {
          return (session1.data.timestamp - session2.data.timestamp) * sortDirectionFactor;
        }
        if (sort.active === '_checked') {
          const session1isChecked = this.isChecked(session1);
          const session2isChecked = this.isChecked(session2);
          if (!session1isChecked && session2isChecked) {
            return 1 * sortDirectionFactor;
          }
          if (session1isChecked && !session2isChecked) {
            return -1 * sortDirectionFactor;
          }
          return 0;
        }
        if (sort.active === '_superState') {
          return (TestSessionsSuperStates.indexOf(session1.state) -
            TestSessionsSuperStates.indexOf(session2.state)) * sortDirectionFactor;
        }
        if (sort.active === '_currentBlock') {
          const s1curBlock = session1.current?.ancestor?.blockId ?? 'zzzzzzzzzz';
          const s2curBlock = session2.current?.ancestor?.blockId ?? 'zzzzzzzzzz';
          return s1curBlock.localeCompare(s2curBlock) * sortDirectionFactor;
        }
        if (sort.active === '_currentUnit') {
          const s1currentUnit = session1.current?.unit?.label ?? 'zzzzzzzzzz';
          const s2currentUnit = session2.current?.unit?.label ?? 'zzzzzzzzzz';
          return s1currentUnit.localeCompare(s2currentUnit) * sortDirectionFactor;
        }
        if (sort.active.startsWith('bookletState:')) {
          const bookletState = sort.active.replace('bookletState:', '');
          const label = (session: TestSession): string =>
            TestSessionUtil.bookletStateLabel(session, bookletState) ?? 'zzzzzzzzzz';
          const a = label(session1);
          const b = label(session2);
          return a.localeCompare(b) * sortDirectionFactor;
        }
        let valA = session1.data[sort.active as keyof typeof session1.data] ?? 'zzzzzzzzzz';
        let valB = session2.data[sort.active as keyof typeof session2.data] ?? 'zzzzzzzzzz';
        if (typeof valA === 'number') {
          valA = valA.toString(10);
        }
        if (typeof valB === 'number') {
          valB = valB.toString(10);
        }
        if ((typeof valA === 'object') || (typeof valB === 'object')) {
          return 0;
        }
        return valA.localeCompare(valB) * sortDirectionFactor;
      });
  }

  isChecked(session: TestSession): boolean {
    return (typeof this._checked[session.data.testId] !== 'undefined');
  }

  checkSessionsBySelection(selected: Selected): void {
    if (this.checkingOptions.autoCheckAll) {
      return;
    }
    let toCheck: TestSession[] = [];
    if (selected.element) {
      if (selected.nthClick === 'first') {
        toCheck = [...this.checked, selected.originSession];
      } else if (selected.nthClick === 'second') {
        toCheck = this._sessions$.getValue()
          .filter(session => (!['pending', 'locked'].includes(session.state)))
          .filter(session => (session.booklet.species === selected.originSession.booklet.species))
          .filter(session => (selected.inversion ? !this.isChecked(session) : true));
      } else if (selected.nthClick === 'third') {
        toCheck = [];
      }
    }

    this.replaceCheckedSessions(toCheck);
  }

  invertChecked(): void {
    if (this.checkingOptions.autoCheckAll) {
      return;
    }
    if (!this._sessions$) {
      return;
    }
    const unChecked = this._sessions$.getValue()
      .filter(session => session.data.testId && BigInt(session.data.testId) > -1n)
      .filter(session => (!['pending', 'locked'].includes(session.state)))
      .filter(session => !this.isChecked(session));
    this.replaceCheckedSessions(unChecked);
  }

  checkSession(session: TestSession): void {
    if (this.checkingOptions.autoCheckAll) {
      return;
    }
    this._checked[session.data.testId] = session;
    this.onCheckedChanged();
  }

  uncheckSession(session: TestSession): void {
    if (this.checkingOptions.autoCheckAll) {
      return;
    }
    delete this._checked[session.data.testId];
    this.onCheckedChanged();
  }

  checkAll(): void {
    if (this.checkingOptions.autoCheckAll) {
      return;
    }
    const allSelectable = this._sessions$.getValue()
      .filter(session => (!['pending', 'locked'].includes(session.state)));
    this.replaceCheckedSessions(allSelectable);
  }

  checkNone(): void {
    this.replaceCheckedSessions([]);
  }

  getMaxTimeAcrossAllSessions(selected: Selected): number {
    const sessions = this.sessions;
    let lowestTime: number = 0;
    sessions.forEach(session => {
      let maxTime;
      if ('units' in session.booklet) {
        const blocks = session.booklet.units.children.filter(testletOrUnit => testletOrUnit.id === selected.element?.id
        );
        if (blocks.length > 0 && 'restrictions' in blocks[0]) {
          maxTime = blocks[0].restrictions.timeMax?.minutes;
        }
      }
      if (maxTime && lowestTime === 0) {
        lowestTime = maxTime;
      }
      if (maxTime && maxTime < lowestTime) {
        lowestTime = maxTime;
      }
    });

    return lowestTime;
  }

  private static groupForGoto(sessionsSet: TestSession[], selection: Selected): GotoCommandData {
    const groupedByTargetUnitAlias: GotoCommandData = {};
    sessionsSet.forEach(session => {
      if (!session.data.bookletName || !isBooklet(session.booklet)) return;

      const ignoreTestlet = (testlet: Testlet) => !!testlet.restrictions.show &&
        !!session.bookletStates &&
        (session.bookletStates[testlet.restrictions.show.if] !== testlet.restrictions.show.is);
      const firstUnit = selection.element?.blockId ?
        BookletUtil.getFirstUnitOfBlock(selection.element.blockId, session.booklet, ignoreTestlet) :
        null;
      if (!firstUnit) return;

      if (!Object.keys(groupedByTargetUnitAlias).includes(firstUnit.alias)) {
        groupedByTargetUnitAlias[firstUnit.alias] = { ids: [session.data.testId], isClosed: undefined };
      } else {
        groupedByTargetUnitAlias[firstUnit.alias].ids.push(session.data.testId);
      }

      if (session.timeLeft && selection.element && Object.keys(session.timeLeft).includes(selection.element.id)) {
        groupedByTargetUnitAlias[firstUnit.alias].isClosed = true;
      }
    });
    return groupedByTargetUnitAlias;
  }

  private static getEmptyStats(): TestSessionSetStat {
    return {
      ...{
        allChecked: false,
        numberOfSessions: 0,
        differentBookletSpecies: 0,
        differentBooklets: 0,
        bookletStateLabels: {},
        pausedSessions: 0,
        lockedSessions: 0
      }
    };
  }

  private static getSessionSetStats(sessionSet: TestSession[], all: number = sessionSet.length): TestSessionSetStat {
    const booklets = new Set();
    const bookletSpecies = new Set();
    const bookletStateLabels: { [key: string]: string } = {};
    let paused = 0;
    let locked = 0;

    sessionSet
      .forEach(session => {
        booklets.add(session.data.bookletName);
        bookletSpecies.add(session.booklet.species);
        Object.values(isBooklet(session.booklet) ? session.booklet?.states : {})
          .forEach(state => {
            bookletStateLabels[state.id] = state.label;
          });
        if (TestSessionUtil.isPaused(session)) paused += 1;
        if (TestSessionUtil.isLocked(session)) locked += 1;
      });

    return {
      numberOfSessions: sessionSet.length,
      differentBooklets: booklets.size,
      differentBookletSpecies: bookletSpecies.size,
      allChecked: (all === sessionSet.length),
      bookletStateLabels,
      pausedSessions: paused,
      lockedSessions: locked
    };
  }

  private synchronizeChecked(sessions: TestSession[]): void {
    const sessionsStats = TestSessionManager.getSessionSetStats(sessions);

    this.checkingOptions.enableAutoCheckAll = (sessionsStats.differentBookletSpecies < 2);

    if (!this.checkingOptions.enableAutoCheckAll) {
      this.checkingOptions.autoCheckAll = false;
    }

    const newCheckedSessions: TestSessionByDataTestId = {};
    sessions
      .forEach(session => {
        if (this.checkingOptions.autoCheckAll || (typeof this._checked[session.data.testId] !== 'undefined')) {
          newCheckedSessions[session.data.testId] = session;
        }
      });
    this._checked = newCheckedSessions;

    this._checkedStats$.next(TestSessionManager.getSessionSetStats(Object.values(this._checked), sessions.length));
    this._sessionsStats$.next(sessionsStats);
  }

  private replaceCheckedSessions(sessionsToCheck: TestSession[]): void {
    const newCheckedSessions: TestSessionByDataTestId = {};
    sessionsToCheck
      .forEach(session => {
        newCheckedSessions[session.data.testId] = session;
      });
    this._checked = newCheckedSessions;
    this.onCheckedChanged();
  }

  private onCheckedChanged(): void {
    this._checkedStats$.next(TestSessionManager.getSessionSetStats(this.checked, this.sessions.length));
  }
}

